function updateSurrenderPanel(){const vote=surrenderVotes[player.team],active=!!vote?.active,retryRemaining=surrenderRetryRemaining(player.team),remaining=Math.max(0,SURRENDER_UNLOCK_MS-(Date.now()-matchStartedAt),retryRemaining),eligible=remaining<=0;$('#surrenderVoteBanner').classList.toggle('hidden',!active||!playing);$('#voteActions').classList.toggle('hidden',!active||!playing);const canVote=active&&playing&&!solo&&vote.members.includes(id)&&!vote.ballots[id]&&Date.now()<vote.endsAt;$('#voteYesBtn').disabled=!canVote;$('#voteNoBtn').disabled=!canVote;if(active){const yes=Object.values(vote.ballots).filter(v=>v==='yes').length,no=Object.values(vote.ballots).filter(v=>v==='no').length;renderSurrenderSlots(vote);$('#voteYes').textContent=yes;$('#voteNo').textContent=no;$('#voteAbstain').textContent=vote.members.length-yes-no;$('#voteSeconds').textContent=Math.max(0,Math.ceil((vote.endsAt-Date.now())/1000));$('#voteThreshold').textContent=surrenderMajority(vote.members.length)}if(!surrenderOpen)return;$('#surrenderTally').classList.toggle('hidden',solo);if(solo){$('#surrenderModalActions').classList.add('hidden');$('#surrenderMessage').textContent='항복을 누르면 투표 없이 즉시 패배 처리되고 봇전이 종료됩니다.';$('#surrenderVoteBtn').disabled=false;$('#surrenderVoteBtn').textContent='즉시 항복';return}$('#surrenderModalActions').classList.toggle('hidden',!active);const modalCanVote=active&&playing&&!solo&&vote.members.includes(id)&&!vote.ballots[id]&&Date.now()<vote.endsAt;$('#surrenderModalYes').disabled=!modalCanVote;$('#surrenderModalNo').disabled=!modalCanVote;$('#surrenderModalSeconds').textContent=active?Math.max(0,Math.ceil((vote.endsAt-Date.now())/1000)):0;$('#surrenderVotes').textContent=active?Object.values(vote.ballots).filter(v=>v==='yes').length:0;$('#surrenderNeeded').textContent=active?surrenderMajority(vote.members.length):teamVoteNeed(player.team);$('#surrenderMessage').textContent=active?'찬성·반대 버튼을 마우스로 클릭하거나 /sp · /nsp를 입력하세요. 팀 전체 과반 찬성 시 항복합니다.':eligible?'항복 투표를 시작합니다. 시작자는 자동으로 찬성하며 팀원에게 15초 투표가 표시됩니다.':retryRemaining>0?'항복 투표가 부결되었습니다. '+formatLockTime(remaining)+' 후 다시 시작할 수 있습니다.':'항복 투표는 경기 진행 5분 후 가능합니다. '+formatLockTime(remaining);$('#surrenderVoteBtn').disabled=!eligible||active;$('#surrenderVoteBtn').textContent=active?'투표 진행 중':eligible?'항복 투표 시작':'LOCKED '+formatLockTime(remaining)}
function castSurrenderVote(){if(playing&&solo&&currentMap!=='training'){finishMatch(player.team==='blue'?'RED':'BLUE',false,player.team);return}if(!playing||solo||Date.now()-matchStartedAt<SURRENDER_UNLOCK_MS||surrenderRetryRemaining(player.team)>0||surrenderVotes[player.team]?.active)return;if(lobbyHost())beginSurrenderVote(id);else send('surrenderStartRequest');closeSurrender()}
