function initAudio(){if(!audioCtx){audioCtx=new(window.AudioContext||window.webkitAudioContext)();noiseBuffer=audioCtx.createBuffer(1,audioCtx.sampleRate*.35,audioCtx.sampleRate);const data=noiseBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1}if(audioCtx.state==='suspended')audioCtx.resume()}
function audioOutput(volume,pan){const gain=audioCtx.createGain();gain.gain.value=volume;let last=gain;if(audioCtx.createStereoPanner){const p=audioCtx.createStereoPanner();p.pan.value=Math.max(-1,Math.min(1,pan||0));gain.connect(p);last=p}last.connect(audioCtx.destination);return gain}
function playGunSound(weapon,volume=1,pan=0){if(!audioCtx)return;const now=audioCtx.currentTime,gun=weapon||'k2',out=audioOutput(volume,pan),noise=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter(),boom=audioCtx.createOscillator(),boomGain=audioCtx.createGain();noise.buffer=noiseBuffer;filter.type='bandpass';filter.frequency.value=gun==='ak47'?1250:gun==='m16'?1900:1550;filter.Q.value=.6;noise.connect(filter);filter.connect(out);out.gain.setValueAtTime(volume,now);out.gain.exponentialRampToValueAtTime(.001,now+(gun==='ak47'?.22:.14));boom.type='triangle';boom.frequency.setValueAtTime(gun==='ak47'?105:gun==='m16'?145:125,now);boom.frequency.exponentialRampToValueAtTime(48,now+.12);boomGain.gain.setValueAtTime(.55,now);boomGain.gain.exponentialRampToValueAtTime(.001,now+.16);boom.connect(boomGain);boomGain.connect(out);noise.start(now);noise.stop(now+.25);boom.start(now);boom.stop(now+.18)}
function playFootstep(volume=.22,pan=0){if(!audioCtx)return;const now=audioCtx.currentTime,out=audioOutput(volume,pan),noise=audioCtx.createBufferSource(),filter=audioCtx.createBiquadFilter();noise.buffer=noiseBuffer;filter.type='lowpass';filter.frequency.value=420;noise.connect(filter);filter.connect(out);out.gain.setValueAtTime(volume,now);out.gain.exponentialRampToValueAtTime(.001,now+.11);noise.start(now);noise.stop(now+.13)}
function toggleAim(){if(player.dead||reloading)return;aiming=!aiming;if(aiming)zoomPower=Math.max(1.5,Math.min(2,zoomPower));targetFOV=aiming?(Math.PI/3)/zoomPower:Math.PI/3;document.body.classList.toggle('aiming',aiming);$('#zoomLevel').classList.toggle('hidden',!aiming);updateZoomLabel()}
addEventListener('keydown',e=>{if(e.code==='Tab'&&playing){e.preventDefault();renderScoreboard();$('#scoreboard').classList.remove('hidden')}});addEventListener('keyup',e=>{if(e.code==='Tab')$('#scoreboard').classList.add('hidden')});
function renderScoreboard(){const roster=[player,...others.values(),...bots];updateMatchScores();for(const side of ['blue','red']){const box=$('#'+side+'Board');box.innerHTML='';for(const p of roster.filter(x=>x.team===side).sort((a,b)=>(b.kills||0)-(a.kills||0))){const row=document.createElement('div');row.className='board-row'+(p.id===id?' me':'');row.innerHTML=`<span>${p.name||'OPERATOR'}<small>${p.team===player.team?(WEAPONS[p.weapon]?.name||'K2 RIFLE'):'HIDDEN'}</small></span><b>${p.kills||0}</b><b>${p.assists||0}</b><b>${p.deaths||0}</b>`;box.appendChild(row)}}}
function adjustZoom(e){if(!playing)return;e.preventDefault();if(!aiming){setFireMode(e.deltaY<0?'auto':'semi');return}zoomPower=Math.max(1.5,Math.min(2,Math.round((zoomPower+(e.deltaY<0?.1:-.1))*10)/10));targetFOV=(Math.PI/3)/zoomPower;updateZoomLabel()}
function setFireMode(mode){fireMode=mode;$('#fireMode').textContent=mode.toUpperCase();$('#fireMode').classList.toggle('semi',mode==='semi');const button=$('#mobileFireMode');if(button){button.textContent=mode==='semi'?'단발':'연사';button.setAttribute('aria-pressed',String(mode==='semi'))}}
function updateZoomLabel(){$('#zoomLevel').textContent=zoomPower.toFixed(1)+'X'}
function resetAim(){aiming=false;zoomPower=1.5;targetFOV=Math.PI/3;document.body.classList.remove('aiming');$('#zoomLevel').classList.add('hidden')}
function wall(x,y){if(MAP[Math.floor(y)]?.[Math.floor(x)]!=='0')return true;return ACTIVE_STRUCTURES.some(o=>Math.hypot(x-o.x,y-o.y)<o.r+.12)}
function loop(t){if(!playing)return;if(touchControls&&t-last<31){requestAnimationFrame(loop);return;}if(matchPaused){last=t;render();requestAnimationFrame(loop);return}const dt=Math.min((t-last)/1000,.04)||0;last=t;update(dt);render();requestAnimationFrame(loop)}
function update(dt){FOV+=(targetFOV-FOV)*Math.min(1,dt*10);updateSurrenderPanel();if(reloading){const now=performance.now(),p=Math.max(0,Math.min(1,(now-reloadStart)/(reloadEnd-reloadStart))),stage=p<.12?'TILT':p<.25?'MAG OUT':p<.4?'BACKPACK':p<.7?'LOADING':p<.9?'MAG IN':'READY';$('#ammo').textContent=Math.max(0,(reloadEnd-now)/1000).toFixed(1);$('#reserveAmmo').textContent='/ '+stage}if(firing&&fireMode==='auto')shoot();if(!player.dead&&(touchControls||document.pointerLockElement===canvas)){let dx=0,dy=0,s=(aiming?2.35:3.1)*dt*(reloading?.5:1);if(touchControls){if(!chatOpen&&!surrenderOpen){dx=(Math.cos(player.a)*touchMoveY-Math.sin(player.a)*touchMoveX)*s;dy=(Math.sin(player.a)*touchMoveY+Math.cos(player.a)*touchMoveX)*s}}else{if(keys.KeyW){dx+=Math.cos(player.a)*s;dy+=Math.sin(player.a)*s}if(keys.KeyS){dx-=Math.cos(player.a)*s;dy-=Math.sin(player.a)*s}if(keys.KeyA){dx+=Math.cos(player.a-1.57)*s;dy+=Math.sin(player.a-1.57)*s}if(keys.KeyD){dx+=Math.cos(player.a+1.57)*s;dy+=Math.sin(player.a+1.57)*s}}if(!wall(player.x+dx,player.y))player.x+=dx;if(!wall(player.x,player.y+dy))player.y+=dy;send('state')}updateCasings(dt);
 if(!coopMode||lobbyHost())for(const b of bots)updateBot(b,dt);for(const [k,v] of others)if(Date.now()-v.seen>30000&&!lobbyPlayers.has(k))others.delete(k);if(solo&&currentMap==='training'){$('#timer').textContent='ESC MENU';return}const left=Math.max(0,endAt-Date.now());$('#timer').textContent=`${String(left/60000|0).padStart(2,'0')}:${String((left/1000|0)%60).padStart(2,'0')}`;if((!coopMode||lobbyHost())&&(!left||blue>=100||red>=100)){const winner=blue===red?'DRAW':blue>red?'BLUE':'RED';finishMatch(winner,true)}}
function finishMatch(winner,broadcast,surrenderSide=null){if(matchEnding||(!playing&&!loading&&finishedMatchRoom===currentRoom))return;finishedMatchRoom=currentRoom;finishedMatchStartedAt=lastSessionMatch?.serverStartedAt||0;window.NeonStrikeInMatch=false;document.body.classList.remove('match-playing');surrenderedTeam=['blue','red'].includes(surrenderSide)?surrenderSide:null;$('#surrenderVoteBanner').classList.add('hidden');$('#fullscreenHint').classList.add('hidden');matchEnding=true;playing=false;$('#scoreboard').classList.add('hidden');$('#mobileTab')?.setAttribute('aria-pressed','false');chatOpen=false;document.body.classList.remove('chat-cursor');surrenderOpen=false;matchPaused=false;if(broadcast&&!solo)send('matchend',{winner,blue,red,surrenderedTeam});if(document.pointerLockElement)document.exitPointerLock();$('#pause').classList.add('hidden');$('#surrenderModal').classList.add('hidden');$('#chatPanel').classList.add('hidden');updateMatchScores();const title=matchResultTitle(winner);$('#winnerText').textContent=title;$('#winnerText').className=winner.toLowerCase();$('#matchEnd').classList.remove('hidden');resultReturnWinner=winner;resultReturnAt=Date.now()+3000;if(resultReturnTimer)clearInterval(resultReturnTimer);advanceResultReturn();resultReturnTimer=setInterval(advanceResultReturn,250)}
function returnAfterMatch(winner){try{localStorage.removeItem('neon-strike-resume')}catch{}try{window.NeonStrikeNative?.stopSession()}catch{}$('#fullscreenHint').classList.add('hidden');$('#leaveBtn').classList.remove('hidden');$('#matchEnd').classList.add('hidden');$('#hud').classList.add('hidden');if(solo){bots.length=0;channel?.close();channel=null;matchEnding=false;if(botLobby){isReady=false;const me=lobbyPlayers.get(id);if(me)me.ready=false;populateBotRoster();$('#matchLobby').classList.remove('hidden');updateLobby()}else{$('#menu').classList.remove('hidden');currentRoom=''}return}others.clear();isReady=false;for(const p of lobbyPlayers.values())p.ready=false;const me=lobbyPlayers.get(id);if(me)me.ready=false;$('#readyBtn').textContent='READY';$('#readyBtn').classList.remove('active');$('#matchLobby').classList.remove('hidden');$('#lobbyStatus').textContent=winner==='DRAW'?'Match ended in a draw. Ready for rematch.':winner+' TEAM WON - Ready for rematch.';updateHUD();matchEnding=false;updateLobby();if(lobbyHost())try{setCoopRoomRunning(false)}catch{}}
function moveBot(b,tx,ty,dt,speed){const desired=Math.atan2(ty-b.y,tx-b.x),diff=Math.atan2(Math.sin(desired-b.a),Math.cos(desired-b.a));b.a+=diff*Math.min(1,dt*3.2);let nx=b.x+Math.cos(b.a)*dt*speed,ny=b.y+Math.sin(b.a)*dt*speed,moved=false;if(!wall(nx,b.y)){b.x=nx;moved=true}if(!wall(b.x,ny)){b.y=ny;moved=true}if(!moved){b.stuck=(b.stuck||0)+dt;if(b.stuck>.12){b.a+=Math.PI/2+(Math.random()-.5)*.7;nx=b.x+Math.cos(b.a)*dt*speed*1.6;ny=b.y+Math.sin(b.a)*dt*speed*1.6;if(!wall(nx,b.y)){b.x=nx;moved=true}if(!wall(b.x,ny)){b.y=ny;moved=true}}}else b.stuck=0;return{moved,diff}}
function botTarget(b){const candidates=[...bots,...others.values()];if(player.team!==b.team&&!player.dead)candidates.push(player);return candidates.filter(t=>t!==b&&!t.dead&&t.team!==b.team).sort((a,c)=>Math.hypot(a.x-b.x,a.y-b.y)-Math.hypot(c.x-b.x,c.y-b.y))[0]||null}
function clearSight(a,b){const d=Math.hypot(b.x-a.x,b.y-a.y);for(let z=.25;z<d-.2;z+=.2)if(wall(a.x+(b.x-a.x)*z/d,a.y+(b.y-a.y)*z/d))return false;return true}
function botHit(attacker,target,amount){if(coopMode&&!lobbyHost())return;const dist=Math.hypot(attacker.x-player.x,attacker.y-player.y),ang=Math.atan2(attacker.y-player.y,attacker.x-player.x)-player.a;playGunSound(attacker.weapon,Math.max(.05,.7-dist*.07),Math.sin(ang));if(target===player){damage(amount,attacker.name);return}if(!target.bot){if(coopMode)send('shot',{target:target.id,damage:amount,name:attacker.name});return}target.hp-=amount;if(target.hp<=0)botKill(attacker,target)}
function awardTeamPoint(victimTeam){if(coopMode&&!lobbyHost()){send('coopPoint');return}if(victimTeam==='blue')red++;else blue++;updateHUD();if(!solo)send('score',{blue,red})}
function botKill(attacker,target){if(target.dead)return;target.dead=true;target.hp=0;attacker.kills=(attacker.kills||0)+1;target.deaths=(target.deaths||0)+1;awardTeamPoint(target.team);feed(attacker.name,target.name);setTimeout(()=>respawnBot(target),2500)}
function updateBot(b,dt){if(b.dead)return;b.cool-=dt;let moved=false;const target=botTarget(b);if(target){const dist=Math.hypot(target.x-b.x,target.y-b.y),desired=Math.atan2(target.y-b.y,target.x-b.x),aimDiff=Math.atan2(Math.sin(desired-b.a),Math.cos(desired-b.a));if(dist>3.2){const motion=moveBot(b,target.x,target.y,dt,.86);moved=motion.moved}else b.a+=aimDiff*Math.min(1,dt*4);if(dist<7&&Math.abs(aimDiff)<.34&&clearSight(b,target)&&b.cool<=0){b.muzzle=performance.now()+90;emitWorldCasing(b);botHit(b,target,WEAPONS[b.weapon]?.damage*.28||9);b.cool=(WEAPONS[b.weapon]?.delay||650)/230+Math.random()*.35}}else{const index=parseInt(b.id.replace('bot',''))||0,orbit=performance.now()/2600+index*2.4,tx=player.x+Math.cos(orbit)*2.1,ty=player.y+Math.sin(orbit)*2.1;if(Math.hypot(tx-b.x,ty-b.y)>.35){const motion=moveBot(b,tx,ty,dt,.82);moved=motion.moved}else b.a+=dt*.45}b.moving=moved;if(moved)b.walk=(b.walk||0)+dt*8}
function selectWeapon(weaponId){if(!playing&&!loadoutSelecting)return;if(!WEAPONS[weaponId]||reloading||loading||performance.now()-meleeStart<MELEE_ANIMATION||player.weapon===weaponId)return;player.weapon=weaponId;const gun=WEAPONS[weaponId];player.ammo=gun.mag;player.reserve=gun.reserve;document.querySelectorAll('.weapon').forEach(b=>{const selected=b.dataset.weapon===weaponId;b.classList.toggle('active',selected);b.setAttribute('aria-pressed',String(selected))});updateWeaponPreview();updateHUD();const me=lobbyPlayers.get(id);if(me&&!playing&&!$('#matchLobby').classList.contains('hidden')){me.weapon=weaponId;if(!loadoutSelecting){me.ready=false;isReady=false;$('#readyBtn').textContent='READY';$('#readyBtn').classList.remove('active');cancelCountdown(lobbyHost())}send('ready',{ready:isReady});updateLobby()}else send('state')}
function reload(){if(performance.now()-meleeStart<MELEE_ANIMATION)return;const gun=WEAPONS[player.weapon];if(!playing||player.dead||reloading||matchPaused||player.ammo===gun.mag||player.reserve<=0)return;reloading=true;resetAim();reloadStart=performance.now();reloadEnd=reloadStart+gun.reload;player.reloadAt=Math.max(Date.now(),(player.reloadAt||0)+1);send('reloadPose');const token=++reloadToken;$('#ammo').textContent=(gun.reload/1000).toFixed(1);$('#reserveAmmo').textContent='/ RELOADING';const complete=()=>{if(token!==reloadToken||!reloading)return;const wait=reloadEnd-performance.now();if(matchPaused||wait>0){setTimeout(complete,Math.max(100,Math.min(500,wait>0?wait:100)));return}const take=Math.min(gun.mag-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;reloading=false;reloadStart=reloadEnd=0;send('reloadPose');updateHUD()};setTimeout(complete,gun.reload)}
function shoot(){const gun=WEAPONS[player.weapon],now=performance.now();if(!playing||matchPaused||chatOpen||surrenderOpen||player.dead||reloading||now-meleeStart<MELEE_ANIMATION||now-lastShot<gun.delay)return;if(player.ammo<=0)return reload();lastShot=now;player.shotAt=Math.max(Date.now(),(player.shotAt||0)+1);send('gunFire');muzzleUntil=now+75;weaponKick=1;ejectCasing();player.ammo--;player.a+=(Math.random()-.5)*(player.weapon==='ak47'?.025:.012);updateHUD();let best=null,bd=player.weapon==='m16'?.1:.12;const range=solo&&currentMap==='training';for(const o of [...others.values(),...bots,...targets]){if(o.dead||(!range&&o.team===player.team))continue;const ang=Math.atan2(o.y-player.y,o.x-player.x),diff=Math.abs(Math.atan2(Math.sin(ang-player.a),Math.cos(ang-player.a))),dist=Math.hypot(o.x-player.x,o.y-player.y);if(diff<bd&&dist<18&&visible(o)){best=o;bd=diff}}if(best){$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');if(best.type==='target')hitTarget(best);else if(best.bot){if(coopMode){if(lobbyHost())handleCoopShot(id,best.id);else send('coopShot',{target:best.id})}else{best.hp-=gun.damage;if(best.hp<=0)kill(best)}}else send('shot',{target:best.id,damage:gun.damage})}else if(range){red++;updateHUD()}}
function hitTarget(target){if(target.dead)return;target.dead=true;blue++;player.kills++;updateHUD();feed(player.name,target.name);setTimeout(()=>{if(playing&&currentMap==='training')target.dead=false},700)}
function gunSoundLocation(source){const dx=source.x-player.x,dy=source.y-player.y,distance=Math.hypot(dx,dy),relative=Math.atan2(dy,dx)-player.a;return{pan:Math.sin(relative),volume:.8/(1+distance*.28)*(clearSight(player,source)?1:.35)}}
function emitWorldCasing(source){const a=source.a||0,rightX=-Math.sin(a),rightY=Math.cos(a);worldCasings.push({x:source.x+Math.cos(a)*.27+rightX*.14,y:source.y+Math.sin(a)*.27+rightY*.14,z:.465,vx:rightX*(.8+Math.random()*.5)+Math.cos(a)*.12,vy:rightY*(.8+Math.random()*.5)+Math.sin(a)*.12,vz:.65+Math.random()*.3,rot:Math.random()*6.28,life:2.5,bounced:false});if(worldCasings.length>48)worldCasings.shift()}
function receiveGunFire(message){if(!playing||solo||matchPaused||message.id===id||!lobbyPlayers.has(message.id)||message.dead||!Number.isFinite(message.shotAt)||!Number.isFinite(message.x)||!Number.isFinite(message.y)||!Number.isFinite(message.a))return;const previous=others.get(message.id);if(message.shotAt<=(previous?.lastFireEffectsAt||0))return;const source={...message,...previous,x:message.x,y:message.y,a:message.a,weapon:message.weapon,shotAt:Math.max(message.shotAt,previous?.shotAt||0),lastFireEffectsAt:message.shotAt,muzzle:performance.now()+100,seen:Date.now()};delete source.type;others.set(message.id,source);const sound=gunSoundLocation(source);playGunSound(source.weapon,sound.volume,sound.pan);emitWorldCasing(source)}
function updateWorldCasings(dt){for(const c of worldCasings){c.life-=dt;c.vz-=2.6*dt;const nx=c.x+c.vx*dt,ny=c.y+c.vy*dt;if(!wall(nx,ny)){c.x=nx;c.y=ny}else{c.vx*=-.3;c.vy*=-.3}c.z+=c.vz*dt;c.rot+=dt*12;if(c.z<0){c.z=0;if(!c.bounced){c.vz=Math.abs(c.vz)*.25;c.vx*=.45;c.vy*=.45;c.bounced=true}else{c.vz=0;c.vx*=Math.max(0,1-dt*8);c.vy*=Math.max(0,1-dt*8)}}}for(let i=worldCasings.length-1;i>=0;i--)if(worldCasings[i].life<=0)worldCasings.splice(i,1)}
