function updateWeaponPreview(){const art=$('#selectedWeaponArt');if(!art)return;art.innerHTML=WEAPON_DESIGNS[player.weapon]||WEAPON_DESIGNS.k2;$('#selectedWeaponLabel').textContent=WEAPONS[player.weapon].name;$('#selectedWeaponLabel').style.color=WEAPONS[player.weapon].color;const details={k2:['BALANCED / 균형형','안정적인 반동과 균형 잡힌 피해량. 다양한 교전에 대응하는 소총입니다.'],ak47:['POWER / 화력형','높은 피해량과 강한 반동. 한 발의 위력을 중시하는 소총입니다.'],m16:['CONTROL / 제어형','빠른 연사와 높은 제어력. 정확하고 지속적인 사격에 적합합니다.']},gun=WEAPONS[player.weapon];$('#draftRole').textContent=details[player.weapon][0];$('#draftDescription').textContent=details[player.weapon][1];$('#draftDamage').textContent=gun.damage;$('#draftRate').textContent=Math.round(60000/gun.delay)+' RPM';$('#draftMagazine').textContent=gun.mag+' ROUNDS';$('#draftTeam').textContent=player.team.toUpperCase()+' TEAM';$('#countdownPanel').style.setProperty('--weapon-accent',gun.color)}
updateWeaponPreview();

function updateDraftRoster(){const list=$('#draftAllies');list.replaceChildren();for(const p of lobbyPlayers.values()){if(p.team!==player.team)continue;const row=document.createElement('div');row.className='draft-ally'+(p.id===id?' me':'');const name=document.createElement('b');name.textContent=p.name+(p.id===id?' (YOU)':'');const gun=document.createElement('span');gun.textContent=WEAPONS[p.weapon]?.name||'K2 RIFLE';row.append(name,gun);list.appendChild(row)}}

function matchLocked(){return (playing||loading||matchEnding)&&currentMap!=='training'}
function leaveToLobby(){if(matchLocked())return;leaveCurrentRoom();location.reload()}
async function requestGameFullscreen(){if(document.fullscreenElement){$('#fullscreenHint').classList.add('hidden');return true}try{if(!document.documentElement.requestFullscreen)throw Error('Fullscreen unavailable');await document.documentElement.requestFullscreen({navigationUI:'hide'});$('#fullscreenHint').classList.add('hidden');return true}catch{if(playing||loading)$('#fullscreenHint').classList.remove('hidden');return false}}
$('#fullscreenHint').onclick=async()=>{if(await requestGameFullscreen())lockGamePointer()};
document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)$('#fullscreenHint').classList.add('hidden');else if(playing||loading)$('#fullscreenHint').classList.remove('hidden')});

function beginSurrenderVote(voter){if(!lobbyHost()||!playing||solo||Date.now()-matchStartedAt<SURRENDER_UNLOCK_MS)return;const side=lobbyPlayers.get(voter)?.team;if(!['blue','red'].includes(side)||surrenderRetryRemaining(side)>0||surrenderVotes[side]?.active)return;const members=surrenderMembers(side);if(!members.includes(voter))return;const vote={id:id+'-'+(++surrenderSequence),side,members,ballots:{[voter]:'yes'},endsAt:Date.now()+SURRENDER_DURATION_MS,active:true,result:''};surrenderVotes[side]=vote;publishSurrenderVote(vote);resolveSurrenderVote(vote)}
function publishSurrenderVote(vote){const snapshot=JSON.parse(JSON.stringify(vote));applySurrenderState(snapshot);send('surrenderState',{vote:snapshot})}
function applySurrenderState(vote){if(!vote||!['blue','red'].includes(vote.side))return;const previous=surrenderRendered[vote.side];surrenderRendered[vote.side]=JSON.parse(JSON.stringify(vote));surrenderVotes[vote.side]=vote;if(vote.side===player.team){if(previous?.id!==vote.id&&vote.active){addChat('SYSTEM','팀 항복 투표 시작: /sp 찬성 · /nsp 반대 (15초)');if(playing&&!solo&&!matchPaused){if(chatOpen){chatOpen=false;document.body.classList.remove('chat-cursor');$('#chatPanel').classList.add('hidden')}openSurrender();surrenderPromptVoteId=vote.id}}for(const [voter,choice] of Object.entries(vote.ballots)){if(previous?.id!==vote.id||previous.ballots[voter]!==choice)addChat(lobbyPlayers.get(voter)?.name||'PLAYER',choice==='yes'?'항복 찬성':'항복 반대',choice)}if(!vote.active&&previous?.active)addChat('SYSTEM',vote.result==='passed'?'과반 찬성으로 항복 처리되었습니다.':vote.result==='rejected'?'항복 투표 종료: 반대 과반으로 부결되었습니다. 3분 후 재투표 가능합니다.':'항복 투표 종료: 과반 찬성 미달로 부결되었습니다. 3분 후 재투표 가능합니다.');if(!vote.active&&surrenderPromptVoteId===vote.id)closeSurrender();}if(!vote.active&&vote.result==='passed'&&(playing||loading)){desertionResult=false;finishMatch(vote.side==='blue'?'RED':'BLUE',false,vote.side)}updateSurrenderPanel()}
function castSurrenderBallot(choice){const vote=surrenderVotes[player.team];if(!playing||solo||!vote?.active||Date.now()>=vote.endsAt||!vote.members.includes(id)){addChat('SYSTEM','현재 우리 팀에서 진행 중인 항복 투표가 없습니다.');return}if(vote.ballots[id]){addChat('SYSTEM','이미 투표했습니다. 중복 투표는 불가합니다.');return}if(lobbyHost())registerSurrenderVote(id,vote.id,choice);else send('surrenderBallot',{voteId:vote.id,choice})}
function resolveSurrenderVote(vote){if(!lobbyHost()||!playing||!vote.active)return;const yes=Object.values(vote.ballots).filter(v=>v==='yes').length,no=Object.values(vote.ballots).filter(v=>v==='no').length,passed=yes>=surrenderMajority(vote.members.length),rejected=no>=surrenderMajority(vote.members.length);if(!passed&&!rejected&&Date.now()<vote.endsAt)return;vote.active=false;vote.result=passed?'passed':rejected?'rejected':'failed';vote.retryAt=passed?0:Date.now()+SURRENDER_RETRY_MS;if(passed)finishMatch(vote.side==='blue'?'RED':'BLUE',true,vote.side);publishSurrenderVote(vote)}
setInterval(()=>{if(!playing)return;if(lobbyHost())for(const vote of Object.values(surrenderVotes))if(vote?.active)resolveSurrenderVote(vote);updateSurrenderPanel()},200);

function renderSurrenderSlots(vote){const list=$('#voteSlots');list.replaceChildren();list.style.gridTemplateColumns='repeat('+vote.members.length+', 36px)';for(let i=0;i<vote.members.length;i++){const voter=vote.members[i],choice=vote.ballots[voter],status=choice==='yes'?'찬성':choice==='no'?'반대':voter?'미투표':'빈 자리',box=document.createElement('span');box.className='vote-slot '+(choice==='yes'?'yes':choice==='no'?'no':voter?'pending':'vacant');box.textContent=choice==='yes'?'✓':choice==='no'?'×':'—';box.title=(voter?(lobbyPlayers.get(voter)?.name||'PLAYER')+' · ':'')+status;box.setAttribute('aria-label',box.title);list.appendChild(box)}}

$('#voteYesBtn').onclick=()=>{castSurrenderBallot('yes');updateSurrenderPanel()};$('#voteNoBtn').onclick=()=>{castSurrenderBallot('no');updateSurrenderPanel()};

function updateMatchScores(){for(const [side,score,selectors] of [['blue',blue,['#blueScore','#boardBlue','#finalBlue']],['red',red,['#redScore','#boardRed','#finalRed']]])for(const selector of selectors){const label=$(selector);label.textContent=surrenderedTeam===side?'항복':score;label.classList.toggle('surrender-score',surrenderedTeam===side)}}

function remotePlayerSnapshot(message,forceSwing=false){const {type,...snapshot}=message,previous=others.get(message.id),token=Number(message.meleeAt)||0;const fresh=token>0&&token>(Number(previous?.meleeAt)||0);snapshot.meleeAt=Math.max(token,Number(previous?.meleeAt)||0);snapshot.remoteMeleeAt=fresh&&(forceSwing||previous)?performance.now():(previous?.remoteMeleeAt??-Infinity);snapshot.muzzle=previous?.muzzle||0;snapshot.lastFireEffectsAt=previous?.lastFireEffectsAt||0;snapshot.shotAt=Math.max(Number(snapshot.shotAt)||0,Number(previous?.shotAt)||0);return applyRemoteReload(snapshot,previous)}
function applyRemoteReload(snapshot,previous){const token=Number(snapshot.reloadAt)||0,prior=Number(previous?.reloadAt)||0;if(token<prior||(previous&&token===prior&&(Number(snapshot.reloadProgress)||0)<(Number(previous.reloadProgress)||0))){for(const key of ['reloadAt','reloadActive','reloadProgress','remoteReloadAt'])snapshot[key]=previous[key];return snapshot}snapshot.reloadAt=token;snapshot.reloadActive=!!snapshot.reloadActive&&!snapshot.dead;snapshot.reloadProgress=Math.max(0,Math.min(1,Number(snapshot.reloadProgress)||0));snapshot.remoteReloadAt=performance.now();return snapshot}
function receiveReloadPose(message){if(!playing||solo||!lobbyPlayers.has(message.id)||!Number.isFinite(message.reloadAt)||message.reloadAt<=0)return;const previous=others.get(message.id);if(message.reloadAt<(Number(previous?.reloadAt)||0))return;if(!previous&&(!Number.isFinite(message.x)||!Number.isFinite(message.y)))return;const snapshot=remotePlayerSnapshot({...message,...previous,reloadAt:message.reloadAt,reloadActive:message.reloadActive,reloadProgress:message.reloadProgress,dead:message.dead});others.set(message.id,{...snapshot,seen:Date.now()})}
