function receiveMeleeSwing(message){if(!playing||solo||matchPaused||!lobbyPlayers.has(message.id)||!Number.isFinite(message.meleeAt)||message.meleeAt<=0)return;const previous=others.get(message.id);if(previous?.dead||message.dead||message.meleeAt<=(Number(previous?.meleeAt)||0))return;if(!previous&&(!Number.isFinite(message.x)||!Number.isFinite(message.y)))return;const snapshot=remotePlayerSnapshot({...message,...previous,meleeAt:message.meleeAt},true);others.set(message.id,{...snapshot,seen:Date.now()})}
