function populateBotRoster(){for(const [key,p] of lobbyPlayers)if(p.bot)lobbyPlayers.delete(key);for(let i=0;i<9;i++){const bot=makeBot(i);lobbyPlayers.set(bot.id,{id:bot.id,name:bot.name,team:bot.team,weapon:bot.weapon,ready:true,bot:true})}}
function enterBotLobby(){if(playing||loading)return;coopMode=false;channel?.close();channel=null;botLobby=true;solo=true;hostId=id;currentRoom='BOT-MATCH';isReady=false;setupPlayer();lobbyPlayers.clear();lobbyPlayers.set(id,{id,name:player.name,team:player.team,weapon:player.weapon,ready:false});populateBotRoster();$('#menu').classList.add('hidden');$('#matchLobby').classList.remove('hidden');$('#lobbyRoom').textContent='PRACTICE';$('#lobbyModeLabel').textContent='P1 + B4 VS B5 · 연습전';$('#copyRoom').classList.add('hidden');selectLobbyMap($('#soloMapSelect').value,false);updateLobby()}

function populateCoopRoster(){for(const [key,p] of lobbyPlayers)if(p.bot)lobbyPlayers.delete(key);const humans=[...lobbyPlayers.values()].filter(p=>!p.bot);for(const p of humans)p.team='blue';for(let i=0;i<humans.length;i++){const p={id:'coopbot'+i,name:['VEX','GHOST','BYTE','VIPER','ONYX'][i],team:'red',weapon:['k2','ak47','m16'][i%3],ready:true,bot:true};lobbyPlayers.set(p.id,p)}}
function createCoopBots(){return [...lobbyPlayers.values()].filter(p=>p.bot).map((p,i)=>{const pts=teamSpawns(p.team),pos=pts[i%pts.length];return{...makeBot(i),...p,x:pos[0],y:pos[1],a:p.team==='blue'?-Math.PI/2:Math.PI/2,hp:100,kills:0,assists:0,deaths:0}})}
function handleCoopShot(shooterId,targetId,attack='shot'){if(!coopMode||!lobbyHost()||!playing||matchPaused)return;const shooter=shooterId===id?player:others.get(shooterId),target=bots.find(b=>b.id===targetId);if(!shooter||shooter.dead||!target||target.dead||target.team===shooter.team||Math.hypot(shooter.x-target.x,shooter.y-target.y)>(attack==='melee'?MELEE_REACH:18)||!clearSight(shooter,target))return;if(attack==='melee'){if(!inMeleeArc(shooter,target)||Date.now()-(coopMeleeTimes.get(shooterId)??-Infinity)<MELEE_COOLDOWN)return;coopMeleeTimes.set(shooterId,Date.now())}target.hp-=attack==='melee'?MELEE_DAMAGE:(WEAPONS[shooter.weapon]?.damage||32);if(target.hp<=0){target.hp=0;target.dead=true;target.deaths++;if(shooterId===id)player.kills++;else shooter.kills=(shooter.kills||0)+1;awardTeamPoint(target.team);feed(shooter.name,target.name);send('coopKill',{killerId:shooterId,killerName:shooter.name,victimName:target.name});setTimeout(()=>respawnBot(target),2500)}}
setInterval(()=>{if(coopMode&&playing&&lobbyHost())send('coopBots',{bots: bots.map(b=>({...b})),blue,red})},100);
