function inMeleeArc(attacker,target){const dx=target.x-attacker.x,dy=target.y-attacker.y,relative=Math.atan2(dy,dx)-(attacker.a||0);return Math.hypot(dx,dy)<=MELEE_REACH&&Math.abs(Math.atan2(Math.sin(relative),Math.cos(relative)))<=MELEE_ARC}
function meleeAttack(){const now=performance.now();if(!playing||matchPaused||chatOpen||surrenderOpen||player.dead||reloading||(!touchControls&&document.pointerLockElement!==canvas)||now-lastMelee<MELEE_COOLDOWN)return;lastMelee=meleeStart=now;player.meleeAt=Math.max(Date.now(),(player.meleeAt||0)+1);send('meleeSwing');firing=false;resetAim();playMeleeSound(false);const range=solo&&currentMap==='training',candidates=[...others.values(),...bots,...targets].filter(o=>!o.dead&&(range||o.team!==player.team)&&inMeleeArc(player,o)&&clearSight(player,o)).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y)),target=candidates[0];send('state');if(!target)return;$('#hitmarker').classList.remove('show');void $('#hitmarker').offsetWidth;$('#hitmarker').classList.add('show');playMeleeSound(true);if(target.type==='target')hitTarget(target);else if(target.bot){if(coopMode){if(lobbyHost())handleCoopShot(id,target.id,'melee');else send('coopShot',{target:target.id,attack:'melee'})}else{target.hp-=MELEE_DAMAGE;if(target.hp<=0)kill(target)}}else send('melee',{target:target.id})}
function receiveMelee(message){if(!playing||solo||matchPaused||player.dead||message.target!==id)return;const source=lobbyPlayers.get(message.id);if(!source||source.bot||source.team===player.team||!Number.isFinite(message.x)||!Number.isFinite(message.y)||!Number.isFinite(message.a)||!inMeleeArc(message,player)||!clearSight(message,player)||Date.now()-(receivedMelee.get(message.id)??-Infinity)<MELEE_COOLDOWN)return;receivedMelee.set(message.id,Date.now());damage(MELEE_DAMAGE,source.name);playMeleeSound(true)}
function playMeleeSound(hit){if(!audioCtx)return;const sound=audioCtx.createOscillator(),gain=audioCtx.createGain(),now=audioCtx.currentTime;sound.type=hit?'triangle':'sine';sound.frequency.setValueAtTime(hit?115:240,now);sound.frequency.exponentialRampToValueAtTime(45,now+.13);gain.gain.setValueAtTime(hit?.35:.1,now);gain.gain.exponentialRampToValueAtTime(.001,now+.17);sound.connect(gain);gain.connect(audioCtx.destination);sound.start(now);sound.stop(now+.18)}

const PRESENCE_PREFIX='neon-strike-online-v1-',PRESENCE_TTL=75000,INVITE_TTL=30000;const presencePeers=new Map(),inviteRequests=new Map();let pendingInvite=null,socialNoticeTimer=null;const presenceChannel=new BroadcastChannel('neon-strike-social-v1');presenceChannel.onmessage=e=>receivePresence(e.data);
function escapeHtml(value){return String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
