function openNicknameDialog(){if(playing||loading||loadoutSelecting)return;$('#nicknameEditInput').value=$('#nameInput').value||'PLAYER';$('#nicknameError').textContent='';$('#nicknameDialog').classList.remove('hidden');$('#nicknameEditInput').focus();$('#nicknameEditInput').select()}
function closeNicknameDialog(){$('#nicknameDialog').classList.add('hidden');$('#changeNicknameBtn').focus()}
function saveNickname(){if(playing||loading||loadoutSelecting)return;const nickname=$('#nicknameEditInput').value.trim().slice(0,20);if(!nickname){$('#nicknameError').textContent='닉네임을 입력해주세요.';return}try{gameStorage.setItem(NICKNAME_KEY,nickname)}catch{$('#nicknameError').textContent='저장할 수 없습니다. 브라우저 저장소 설정을 확인해주세요.';return}$('#nameInput').value=nickname;player.name=nickname.toUpperCase();updateNicknameLabel();const me=lobbyPlayers.get(id);if(me){me.name=player.name;if(!$('#matchLobby').classList.contains('hidden')){send('ready',{ready:isReady});updateLobby()}}closeNicknameDialog();publishPresence();socialNotice('닉네임을 저장했습니다.')}
function presenceStatus(){if(playing||loading||matchEnding)return'playing';if(loadoutSelecting)return'selecting';if(!$('#matchLobby').classList.contains('hidden'))return botLobby?'practice':'room';return'idle'}
let presenceRemoved=false;
function publishPresence(){if(presenceRemoved)return;const peer={id,name:player.name||'PLAYER',room:roomRegistered?currentRoom:'',status:presenceStatus(),seen:Date.now()};presencePeers.set(id,peer);try{gameStorage.setItem(PRESENCE_PREFIX+id,JSON.stringify(peer))}catch{}presenceChannel.postMessage({type:'presence',peer});refreshPresence()}
function refreshPresence(){const active=new Map();let complete=false;try{for(let i=0;i<gameStorage.length;i++){const key=gameStorage.key(i);if(!key?.startsWith(PRESENCE_PREFIX))continue;const peer=JSON.parse(gameStorage.getItem(key)||'null');if(peer?.id&&Number.isFinite(peer.seen)&&Date.now()-peer.seen<PRESENCE_TTL)active.set(peer.id,peer)}complete=true}catch{}if(complete){presencePeers.clear();for(const [key,peer] of active)presencePeers.set(key,peer)}else for(const [key,peer] of presencePeers)if(Date.now()-peer.seen>=PRESENCE_TTL)presencePeers.delete(key);renderOnlinePlayers()}
function removePresence(){if(presenceRemoved)return;presenceRemoved=true;try{gameStorage.removeItem(PRESENCE_PREFIX+id)}catch{gameStorage.removeOnExit?.(PRESENCE_PREFIX+id)}presencePeers.delete(id);presenceChannel.postMessage({type:'offline',id,seen:Date.now()});presenceChannel.close()}

function canInvitePlayers(){const room=readRooms().find(r=>r.code===currentRoom);return roomRegistered&&!$('#matchLobby').classList.contains('hidden')&&!botLobby&&!playing&&!loading&&!loadoutSelecting&&!!room&&!room.inMatch&&room.players<(room.mode==='coop'?TEAM_CAPACITY:ROOM_CAPACITY)}
function renderOnlinePlayers(){const peers=[...presencePeers.values()].filter(p=>p.id!==id).sort((a,b)=>(a.status==='idle'?0:1)-(b.status==='idle'?0:1)||a.name.localeCompare(b.name));document.querySelectorAll('.online-count').forEach(el=>el.textContent=peers.length+'명');$('#invitePlayersCount').textContent=peers.filter(p=>p.status==='idle'&&!p.room).length+'명';for(const list of document.querySelectorAll('.online-player-list')){const inviteList=list.dataset.invite==='true',visible=list.dataset.lobbyOnly==='true'?peers.filter(p=>p.status==='idle'&&!p.room):peers;const viewKey=JSON.stringify([canInvitePlayers(),visible.map(p=>[p.id,p.name,p.status,p.room,[...inviteRequests.values()].some(v=>v.targetId===p.id&&v.expiresAt>Date.now())])]);if(list.dataset.viewKey===viewKey)continue;list.dataset.viewKey=viewKey;list.replaceChildren();if(!visible.length){const empty=document.createElement('div');empty.className='online-empty';empty.textContent=inviteList?'현재 로비에 있는 초대 가능한 플레이어가 없습니다.':'다른 접속 플레이어가 없습니다.';list.appendChild(empty)}for(const peer of visible){const row=document.createElement('div');row.className='online-player';const info=document.createElement('div'),name=document.createElement('b'),status=document.createElement('small');name.textContent=peer.name;status.textContent=peer.status==='idle'?'로비':peer.status==='room'?'방 참가 중':peer.status==='selecting'?'총 선택 중':peer.status==='practice'?'연습전 대기':'경기 중';info.append(name,status);row.appendChild(info);if(inviteList){const pending=[...inviteRequests.values()].some(v=>v.targetId===peer.id&&v.expiresAt>Date.now()),button=document.createElement('button');button.textContent=pending?'초대 보냄':'이 방으로 초대';button.disabled=pending||!canInvitePlayers();button.onclick=()=>{invitePlayer(peer.id);renderOnlinePlayers()};row.appendChild(button)}list.appendChild(row)}}}
function invitePlayer(targetId){refreshPresence();const peer=presencePeers.get(targetId);if(!canInvitePlayers()||!peer||peer.status!=='idle'||peer.room){socialNotice('지금은 해당 플레이어를 초대할 수 없습니다.');return}const existing=[...inviteRequests.values()].some(v=>v.targetId===targetId&&v.expiresAt>Date.now());if(existing){socialNotice('이미 초대를 보냈습니다. 응답을 기다려주세요.');return}const room=readRooms().find(r=>r.code===currentRoom),invite={token:id+'-'+Math.random().toString(36).slice(2),fromId:id,fromName:player.name,targetId,room:currentRoom,mode:room.mode||'pvp',expiresAt:Date.now()+INVITE_TTL};inviteRequests.set(invite.token,invite);presenceChannel.postMessage({type:'invite',invite});socialNotice(peer.name+'님에게 초대를 보냈습니다.')}
function receivePresence(message){if(!message||typeof message!=='object')return;if(message.type==='presence'){const peer=message.peer;if(peer?.id&&peer.id!==id&&typeof peer.name==='string'&&Number.isFinite(peer.seen)){presencePeers.set(peer.id,peer);renderOnlinePlayers()}return}if(message.type==='offline'){presencePeers.delete(message.id);renderOnlinePlayers();return}if(message.type==='invite'){const invite=message.invite;if(!invite||invite.targetId!==id||invite.expiresAt<=Date.now()||invite.fromId===id)return;if(presenceStatus()!=='idle'||pendingInvite){presenceChannel.postMessage({type:'inviteReply',token:invite.token,targetId:invite.fromId,fromId:id,accepted:false});return}pendingInvite=invite;$('#inviteMessage').textContent=invite.fromName+'님이 '+(invite.mode==='coop'?'PLAYER TEAM VS BOT TEAM':'PLAYER TEAM VS PLAYER TEAM')+' 방 ('+invite.room+')으로 초대했습니다.';$('#inviteDialog').classList.remove('hidden');$('#acceptInviteBtn').focus();updateInviteExpiry();return}if(message.type==='inviteReply'&&message.targetId===id){const invitation=inviteRequests.get(message.token);if(!invitation||invitation.targetId!==message.fromId)return;inviteRequests.delete(message.token);socialNotice((presencePeers.get(message.fromId)?.name||'플레이어')+(message.accepted?'님이 초대를 수락했습니다.':'님이 초대를 거절했거나 참가할 수 없습니다.'))}}
