function acceptInvite(){if(!pendingInvite)return;const invitation=pendingInvite,room=readRooms().find(r=>r.code===invitation.room);if(presenceStatus()!=='idle'||Date.now()>=invitation.expiresAt||!room||room.inMatch||room.players>=(room.mode==='coop'?TEAM_CAPACITY:ROOM_CAPACITY)){declineInvite();socialNotice('방이 가득 찼거나 초대가 만료되었습니다.');return}closeInviteDialog();$('#roomInput').value=invitation.room;joinByCode();const accepted=roomRegistered&&currentRoom===invitation.room;presenceChannel.postMessage({type:'inviteReply',token:invitation.token,targetId:invitation.fromId,fromId:id,accepted});publishPresence()}
