// The server owns disconnect deadlines even when all WebViews stop rendering.
let sessionLeaving=false,sessionNeedsJoin=true;let sessionBusy=false,resumePending=null,desertionResult=false,lastSessionMatch=null;
function saveMatchResume(){if(solo||!currentRoom||(!playing&&!loading))return;try{localStorage.setItem('neon-strike-resume',JSON.stringify({id,room:currentRoom,team:player.team,weapon:player.weapon,name:player.name,map:currentMap,saved:Date.now()}))}catch{}}
function sessionExit(){sessionLeaving=true;if(!currentRoom)return;const body=JSON.stringify({id,room:currentRoom,action:'leave',sentAt:Date.now()});try{navigator.sendBeacon?.('/api/session',new Blob([body],{type:'application/json'}))}catch{}confirmSessionExit(body);try{window.NeonStrikeNative?.stopSession()}catch{}}
function abortWeaponSelection(){if(playing||loading)return;cancelCountdown(lobbyHost());isReady=false;for(const p of lobbyPlayers.values())p.ready=false;send('ready',{ready:false});$('#matchLobby').classList.remove('hidden');$('#lobbyStatus').textContent='총 선택 중 참가자가 나가 선택이 취소되었습니다. 다시 준비해 주세요.';updateLobby()}
async function pollMatchSession(){if(sessionLeaving||sessionBusy||!currentRoom||solo||botLobby)return;sessionBusy=true;try{const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,room:currentRoom,action:sessionNeedsJoin?'join':'ping',sentAt:Date.now(),name:player.name,team:player.team}),signal:AbortSignal.timeout(3000)});if(!response.ok)return;const result=await response.json();if(sessionLeaving)return;sessionNeedsJoin=false;serverClockOffset=Number.isFinite(result.serverTime)?result.serverTime-Date.now():0;const m=result.match?{...result.match,serverStartedAt:result.match.startedAt,startedAt:result.match.startedAt?result.match.startedAt-serverClockOffset:0}:null;lastSessionMatch=m;applyMatchLoadouts(m);if(playing&&m?.stage==='running')restoreRemotePlayers(result.players);if(m&&['draft','running'].includes(m.stage)&&!isFinishedRunningMatch(m))window.NeonStrikeNative?.setSession(location.origin,id,currentRoom);else window.NeonStrikeNative?.stopSession();if(m?.stage==='draft'&&roomRegistered&&!playing&&!loading&&!matchEnding&&m.draftEndsAt>0)showCountdown(Math.max(0,Math.ceil((m.draftEndsAt-result.serverTime)/1000)));if(!m){if(resumePending){resumePending=null;localStorage.removeItem('neon-strike-resume');channel?.close();channel=null;currentRoom=''}return}if(m.stage==='lobby'&&loadoutSelecting){abortWeaponSelection();return}if(resumePending){const saved=resumePending;resumePending=null;if(m.stage!=='running'||!m.roster.some(p=>p.id===id)){localStorage.removeItem('neon-strike-resume');channel?.close();channel=null;currentRoom='';return}team=player.team=saved.team;player.weapon=saved.weapon;player.name=saved.name;hostId=readRooms().find(r=>r.code===currentRoom)?.hostId||'';roomRegistered=true;coopMode=readRooms().find(r=>r.code===currentRoom)?.mode==='coop';for(const p of m.roster)lobbyPlayers.set(p.id,{...p,weapon:'k2',ready:false});start(false,m.map);return}if(!playing&&!loading&&!matchEnding&&m.stage==='running'&&roomRegistered&&!isFinishedRunningMatch(m)){cancelCountdown(false);start(false,m.map);return}if(playing&&m.stage==='running'){matchStartedAt=m.startedAt;endAt=m.startedAt+1500000;saveMatchResume()}if((playing||loading)&&m.stage==='ended'){if(loadClock){clearInterval(loadClock);loadClock=null}loading=false;$('#loadingScreen').classList.add('hidden');blue=m.blue;red=m.red;desertionResult=!!m.desertion;finishMatch(m.winner,false,m.surrenderedTeam)}}catch{}finally{sessionBusy=false}}
setInterval(pollMatchSession,1000);
addEventListener('visibilitychange',()=>{if(document.hidden){firing=false;touchMoveX=touchMoveY=0;for(const k of Object.keys(keys))keys[k]=0;saveMatchResume()}else{pollMatchSession();if(playing&&!solo&&surrenderOpen)closeSurrender()}});
setInterval(()=>{if(document.hidden&&playing&&!matchPaused){last=performance.now();update(.1);send('state')}},100);
try{const saved=JSON.parse(localStorage.getItem('neon-strike-resume')||'null');if(saved?.id&&saved.room){resumePending=saved;$('#nameInput').value=saved.name;$('#roomInput').value=saved.room;currentRoom=saved.room;connectRoom();pollMatchSession()}else localStorage.removeItem('neon-strike-resume')}catch{}

// Keep stationary, pointer-unlocked and chat-active players visible to peers.
function publishMatchState(){if(playing&&!solo&&channel)send('state')}
function restoreRemotePlayers(peers){if(!Array.isArray(peers))return;for(const snapshot of peers){if(snapshot?.id===id||!Number.isFinite(snapshot?.x)||!Number.isFinite(snapshot?.y))continue;receive({...snapshot,type:'state'})}}
setInterval(publishMatchState,500);

let loadingEndsAt=0,serverClockOffset=0;
function advanceLoading(){if(!loading||playing||matchEnding)return;const seconds=Math.max(0,Math.ceil((loadingEndsAt-Date.now())/1000));$('#loadTimer').textContent=seconds;if(!seconds){clearInterval(loadClock);loadClock=null;beginGameplay()}}
async function registerServerDraft(){if(botLobby||solo||!window.NeonStrikeServerConnected||!currentRoom)return;try{const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,room:currentRoom,action:'draft',map:currentMap}),signal:AbortSignal.timeout(3000)});if(response.ok)pollMatchSession()}catch{}}
addEventListener('focus',()=>{advanceLoading();pollMatchSession()});
addEventListener('visibilitychange',()=>{if(!document.hidden)advanceLoading()});
function resizeDraftViewport(){const viewport=window.visualViewport,style=document.documentElement.style;style.setProperty('--draft-viewport-height',(viewport?.height||innerHeight)+'px');style.setProperty('--ui-height',(viewport?.height||innerHeight)+'px');style.setProperty('--ui-width',(viewport?.width||innerWidth)+'px');style.setProperty('--ui-left',(viewport?.offsetLeft||0)+'px');style.setProperty('--ui-top',(viewport?.offsetTop||0)+'px')}
addEventListener('resize',resizeDraftViewport);window.visualViewport?.addEventListener('resize',resizeDraftViewport);window.visualViewport?.addEventListener('scroll',resizeDraftViewport);resizeDraftViewport();

function roomListKey(rooms){return JSON.stringify(rooms.map(r=>[r.code,r.mode,r.host,r.players,!!r.inMatch]))}

function matchResultTitle(winner){if(winner==='DRAW')return 'DRAW';if(desertionResult)return winner.toLowerCase()===player.team?'전원 탈주 승리':'전원 탈주 패배';return winner+' TEAM WINS'}

let resultReturnAt=0,resultReturnWinner='',resultReturnTimer=null;
function advanceResultReturn(){if(!matchEnding||!resultReturnAt)return;const seconds=Math.max(0,Math.ceil((resultReturnAt-Date.now())/1000));$('#returnTimer').textContent=seconds;if(!seconds){clearInterval(resultReturnTimer);resultReturnTimer=null;resultReturnAt=0;returnAfterMatch(resultReturnWinner)}}
addEventListener('focus',advanceResultReturn);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)advanceResultReturn()});

try{localStorage.setItem('neon-strike-player-id',id);sessionStorage.setItem('neon-strike-player-id',id)}catch{}
let finishedMatchRoom='',finishedMatchStartedAt=0;
function isFinishedRunningMatch(m){return !!m&&m.stage==='running'&&finishedMatchRoom===currentRoom&&(!finishedMatchStartedAt||m.serverStartedAt===finishedMatchStartedAt)}

function changeMobileZoom(direction){if(!playing||matchPaused||chatOpen||surrenderOpen||player.dead||reloading)return;if(!aiming){if(direction<0)return;toggleAim()}zoomPower=Math.max(1.5,Math.min(2,Math.round((zoomPower+direction*.05)*100)/100));targetFOV=(Math.PI/3)/zoomPower;updateZoomLabel()}
if(touchControls){const zoom=document.createElement('div');zoom.id='mobileZoomControls';zoom.innerHTML='<button aria-label="축소" id="mobileZoomOut">−</button><button aria-label="확대" id="mobileZoomIn">＋</button>';$('#hud').appendChild(zoom);for(const [selector,direction] of [['#mobileZoomOut',-1],['#mobileZoomIn',1]]){const button=$(selector);let timer=null,pointer=null;const stop=()=>{if(timer)clearInterval(timer);timer=null;pointer=null};button.onpointerdown=e=>{e.preventDefault();e.stopPropagation();stop();pointer=e.pointerId;button.setPointerCapture(pointer);changeMobileZoom(direction);timer=setInterval(()=>changeMobileZoom(direction),100)};button.onpointerup=button.onpointercancel=button.onlostpointercapture=stop;addEventListener('blur',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()})}}

function toggleMobileFireMode(){if(!playing||matchPaused||chatOpen||surrenderOpen||player.dead||reloading)return;firing=false;setFireMode(fireMode==='auto'?'semi':'auto')}

async function confirmSessionExit(body){for(let attempt=0;attempt<3&&sessionLeaving;attempt++){try{const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body,keepalive:true,signal:AbortSignal.timeout(3000)});if(response.ok)return}catch{}if(attempt<2)await new Promise(resolve=>setTimeout(resolve,500))}}

function toggleMobileScoreboard(){if(!playing||matchPaused||chatOpen||surrenderOpen)return;const board=$('#scoreboard'),open=board.classList.contains('hidden');firing=false;renderScoreboard();board.classList.toggle('hidden',!open);$('#mobileTab')?.setAttribute('aria-pressed',String(open))}
if(touchControls){const tab=document.createElement('button');tab.id='mobileTab';tab.textContent='TAB';tab.setAttribute('aria-label','점수표 열기·닫기');tab.setAttribute('aria-pressed','false');document.body.appendChild(tab);tab.onclick=e=>{e.preventDefault();e.stopPropagation();toggleMobileScoreboard()};setInterval(()=>{if(playing&&!$('#scoreboard').classList.contains('hidden'))renderScoreboard()},500)}
